// Group manages goroutines and collect all the errors.
// See https://pkg.go.dev/golang.org/x/sync/errgroup#group for more information
type Group interface {
	Ctx() context.Context
	Wait() error
	Go(name string, f func(logger *zap.Logger) error)
}

type group struct {
	ctx          context.Context
	cancel       context.CancelFunc
	logger       *zap.Logger
	panicHandler func(any)

	wg sync.WaitGroup

	errMutex sync.Mutex
	err      error
}

// GroupOption customizes a Group during construction with NewGroup.
type GroupOption func(*group)

// WithContext associates a Context with the Group.
// The context will be canceled if any goroutine returns an error.
// See https://pkg.go.dev/golang.org/x/sync/errgroup#WithContext
func WithContext(ctx context.Context) GroupOption {
	return func(g *group) {
		g.ctx, g.cancel = context.WithCancel(ctx)
	}
}

// WithPanicHandler sets a panic handler for the group.
func WithPanicHandler(f func(any)) GroupOption {
	return func(g *group) {
		g.panicHandler = f
	}
}

// NewGroup returns a new Group.
func NewGroup(logger *zap.Logger, opts ...GroupOption) Group {
	g := &group{
		ctx:          context.Background(),
		cancel:       nil, // Set separately by WithContext
		panicHandler: nil, // Set separately by WithPanicHandler
		logger:       logger,
		wg:           sync.WaitGroup{},

		errMutex: sync.Mutex{},
		err:      nil,
	}
	for _, opt := range opts {
		opt(g)
	}
	return g
}

// Ctx returns the Context associated with the Group.
func (g *group) Ctx() context.Context {
	return g.ctx
}
